        "label": "Recipe 07",
        "language": "ts",
        "code": "// ===== EXAMPLE 07-filters =====\nconst recipe07: Recipe = (() : any => {\n\n\n\nconst meta: any={id:'07',title:'Eighteen ways to see',category:'Image effects',description:'All seventeen public filters plus the original, with parameter choices that make their differences inspectable.'};\nasync function run(): Promise<any> {\n  const src: any=await plate(360,230),sourceName: any='07-filter-source.png';await save(sourceName,src);\n  const filters: any=[{type:'gaussianBlur',intensity:4},{type:'motionBlur',intensity:11,angle:25},{type:'radialBlur',intensity:12},{type:'sharpen',intensity:2},{type:'noise',intensity:.25},{type:'grain',intensity:.3},{type:'edgeDetection'},{type:'emboss'},{type:'invert'},{type:'grayscale'},{type:'sepia'},{type:'pixelate',size:12},{type:'brightness',value:30},{type:'contrast',value:40},{type:'saturation',value:60},{type:'hueShift',value:100},{type:'posterize',levels:5}];\n  const layers: any=heading('07 / IMAGE LAB','Eighteen ways to see','Original plus the complete filter family. Each treatment is generated independently.');\n  for(const item of filters){\n    if(['edgeDetection','emboss'].includes(item.type))item.intensity=1;\n    // image.effects brightness is -1..1; contrast is -255..254.\n    // createImage.filters uses percentages for both; these contracts differ.\n    if(item.type==='brightness')item.value/=100;\n  }\n  const all: any=[{type:'original'},...filters],knownIssues: any=[];\n  for(let i: any=0;i<all.length;i++){\n    const item: any=all[i],x: any=64+(i%3)*450,y: any=244+Math.floor(i/3)*330;\n    let buffer: any=src,fallback: any=false;\n    if(i)try{buffer=await p.image.effects(path.join(OUT,sourceName),[item]);}catch(error: any){\n      // Pinned upstream filter bug: grayscale emits a single-channel raw raster,\n      // but the filter pipeline requires four channels. Do not hide this failure.\n      if(!(error instanceof ApexifyDecodeError)||!['grayscale','edgeDetection'].includes(item.type)||!error.message.includes('geometry'))throw error;\n      fallback=true;knownIssues.push({feature:item.type,error:error.message,alternative:'Explicit painter.pixels implementation'});\n      if(item.type==='grayscale')buffer=await p.pixels.manipulate(src,{filter:'grayscale'});\n      else{\n        const pix: any=await p.pixels.getData(src),copy: any=new Uint8ClampedArray(pix.data),w: any=pix.width,h: any=pix.height;\n        const luminance: any=(x: any,y: any): any =>{const n: any=(y*w+x)*4;return .2126*copy[n]+.7152*copy[n+1]+.0722*copy[n+2];};\n        for(let y: any=1;y<h-1;y++)for(let x: any=1;x<w-1;x++){\n          const gx: any=-luminance(x-1,y-1)+luminance(x+1,y-1)-2*luminance(x-1,y)+2*luminance(x+1,y)-luminance(x-1,y+1)+luminance(x+1,y+1);\n          const gy: any=-luminance(x-1,y-1)-2*luminance(x,y-1)-luminance(x+1,y-1)+luminance(x-1,y+1)+2*luminance(x,y+1)+luminance(x+1,y+1);\n          const n: any=(y*w+x)*4,m: any=Math.min(255,Math.hypot(gx,gy));pix.data[n]=pix.data[n+1]=pix.data[n+2]=m;\n        }\n        buffer=await p.pixels.setData(src,pix);\n      }\n    }\n    layers.push({type:'imageBuffer',buffer,x,y,width:412,height:264},textLayer(txt(item.type+(fallback?' *':''),x,y+278,19,C.ink,{font:font(19,'mono')})));\n  }\n  layers.push(textLayer(txt('* Upstream channel error reproduced; displayed result uses the documented pixel-based alternative.',64,2220,14,C.red)));\n  return [await save('07-filters.png',await scene(1440,2290,layers)),await json('07-known-filter-issues.json',knownIssues)];\n}\n\nreturn {meta,run};\n})();"
