        "code": "// ===== EXAMPLE 08-masks-and-warp =====\nconst recipe08: Recipe = (() : any => {\n\nconst meta: any={id:'08',title:'Mutable matter',category:'Image effects',description:'Alpha and luminance masks, geometric clipping, all distortion types, mesh warping, grouped transforms and optical effects.'};\nasync function run(): Promise<any> {\n  const w: any=380,h: any=280,source: any=await plate(w,h),mask: any=await scene(w,h,[images(circle(190,140,123,'#ffffff'),rect(20,122,340,36,'#ffffff'))],{transparentBase:true});\n  const treatments: any=[\n    ['Alpha mask',{mask:{source:mask,mode:'alpha'}}],\n    ['Polygon clipping',{clipPath:[{x:20,y:100},{x:200,y:10},{x:360,y:100},{x:300,y:265},{x:85,y:245}]}],\n    ['Perspective',{distortion:{type:'perspective',points:[{x:25,y:20},{x:350,y:48},{x:320,y:260},{x:50,y:220}]}}],\n    ['Warp',{distortion:{type:'warp',intensity:.26}}],\n    ['Bulge',{distortion:{type:'bulge',intensity:.55}}],\n    ['Pinch',{distortion:{type:'pinch',intensity:.6}}],\n    ['Mesh displacement',{meshWarp:{gridX:2,gridY:2,controlPoints:Array.from({length:3},(_: any,y: any): any =>Array.from({length:3},(_: any,x: any): any =>({x:x*w/2+(y===1?30:0),y:y*h/2+(x===1?-25:0)})))}}],\n    ['Optical stack',{effects:{vignette:{intensity:.7,size:.7},chromaticAberration:{intensity:5},filmGrain:{intensity:.08},lensFlare:{x:240,y:80,intensity:.4}}}],\n    ['Group transform',{}]\n  ];\n  const layers: any=heading('08 / RASTER TRANSFORMATIONS','Mutable matter','One source. Nine controlled transformations. The mask and mesh are generated from code.');\n  for(let i: any=0;i<treatments.length;i++){\n    const [title,opts]=treatments[i],base: any=await p.createCanvas({width:w,height:h,colorBg:'#e2ddd2'});\n    const buffer: any=await p.createImage({source,x:0,y:0,width:w,height:h,...opts},base,i===8?{isGrouped:true,groupTransform:{rotation:-9,scaleX:.82,scaleY:.82,pivotX:w/2,pivotY:h/2,opacity:.9}}:undefined);\n    const x: any=64+i%3*450,y: any=245+Math.floor(i/3)*358;\n    layers.push({type:'imageBuffer',buffer,x,y,width:410,height:302},textLayer(txt(title,x,y+318,18,C.ink,{font:font(18,'mono')})));\n  }\n  return [await save('08-masks-and-warp.png',await scene(1440,1350,layers))];\n}\n\nreturn {meta,run};\n})();"
