        "code": "// ===== EXAMPLE 09-image-utilities =====\nconst recipe09: Recipe = (() : any => {\n\n\nconst meta: any={id:'09',title:'The image finishing desk',category:'Image utilities',description:'Every local image utility: masked duotones, cutouts, blend layers, palette algorithms, compression, conversion, resizing, stitch and three collage layouts.'};\nasync function run(): Promise<any> {\n  const src: any=await plate(600,400);await save('09-source.png',src);const source: any=path.join(OUT,'09-source.png');\n  const mask: any=await scene(600,400,[images(circle(300,200,180,'#fff'))],{transparentBase:true});\n  const cut: any=await p.image.masking(src,mask,{type:'alpha'});\n  const gradient: any=await p.image.gradientBlend(src,{type:'linear',angle:45,colors:[{stop:0,color:C.blue},{stop:.5,color:C.red},{stop:1,color:C.gold}],blendMode:'screen'});\n  const tinted: any=await p.image.colorsFilter(source,C.teal,.38);\n  const keyed: any=await scene(600,400,[images(circle(300,200,180,C.red))],{colorBg:'#00ff00'});await save('09-key-source.png',keyed);\n  const removed: any=await p.image.colorsRemover(path.join(OUT,'09-key-source.png'),{red:0,green:255,blue:0});\n  const blended: any=await p.image.blend([{image:cut,blendMode:'screen',opacity:.6,position:{x:0,y:0}},{image:removed,blendMode:'multiply',opacity:.6}],src);\n  const pts: any=[{x:40,y:40},{x:500,y:80},{x:570,y:320},{x:80,y:365}];\n  const crop: any=await p.image.cropImage({imageSource:source,crop:'inner',radius:24,coordinates:pts.map((point: any,i: any): any =>({from:point,to:pts[(i+1)%pts.length]}))});\n  const resized: any=await p.image.resize({imagePath:src,size:{width:300,height:200},maintainAspectRatio:true,outputFormat:'png'});\n  const previews: any=[src,cut,gradient,tinted,blended,crop];\n  const names: any=['Original','Alpha mask','Gradient blend','Colour filter','Layer blend','Path crop'];\n  const layers: any=heading('09 / FINISHING','The image finishing desk','A practical asset pipeline, from procedural source to delivery formats.');\n  for(let i: any=0;i<previews.length;i++){const x: any=64+i%3*450,y: any=245+Math.floor(i/3)*335;layers.push({type:'imageBuffer',buffer:previews[i],x,y,width:410,height:273},textLayer(txt(names[i],x,y+286,19,C.ink)));}\n  const palettes: any={};for(const method of ['kmeans','median-cut','octree'])palettes[method]=await p.image.extractPalette(src,{method,count:7,format:'hex'});\n  palettes.kmeans.forEach((s: any,i: any): any =>layers.push(images(rect(64+i*188,974,188,70,s.color)),textLayer(txt(s.color,64+i*188,1061,16,C.ink,{font:font(16,'mono')}))));\n  const files: any=[await save('09-image-utilities.png',await scene(1440,1150,layers)),await save('09-alpha-cutout.png',cut),await save('09-color-key-cutout.png',removed),await save('09-resized.png',resized)];\n  for(const format of ['jpeg','webp','avif'])files.push(await save(`09-delivery.${format}`,await p.image.compress(src,{format,quality:84,maxWidth:600})));\n  files.push(await save('09-converted.webp',await p.image.imgConverter(src,'webp')));\n  const thumbs: any=await Promise.all(previews.map((imagePath: any): any =>p.image.resize({imagePath,size:{width:280,height:187},outputFormat:'png'})));\n  files.push(await save('09-stitch.png',await p.image.stitchImages(thumbs,{direction:'horizontal',spacing:12})));\n  for(const type of ['grid','masonry','carousel'])files.push(await save(`09-collage-${type}.png`,await p.image.createCollage(thumbs.map((source: any): any =>({source})),{type,columns:3,spacing:14,background:C.paper,borderRadius:14})));\n  files.push(await json('09-image-analysis.json',{palettes,colorAnalysis:await p.image.colorAnalysis(source),validHex:p.image.validHex(C.red)}));return files;\n}\n\nreturn {meta,run};\n})();"
