        "code": "// ===== EXAMPLE 10-line-chart =====\nconst recipe10: Recipe = (() : any => {\n\n\nconst meta: any={id:'10',title:'Growth under uncertainty',category:'Charts',description:'A multi-series time course with explicit uncertainty bounds, error bars, curve smoothing and an annotated secondary process. All data are synthetic.'};\nasync function run(): Promise<any> {\n  const growth: any=(t: any): any =>8+83/(1+Math.exp(-(t-10)/2.7));\n  const a: any=series('Culture A',C.red,growth),b: any=series('Culture B',C.blue,(t: any): any =>4+72/(1+Math.exp(-(t-13)/3.2)));\n  a.area={type:'around',show:true,color:C.red,opacity:.14,lowerBound:a.data.map((d: any): any =>d.y-5),upperBound:a.data.map((d: any): any =>d.y+5)};\n  a.errorBar={show:true,color:C.red,width:1.5,capSize:6};\n  a.data=a.data.map((d: any,i: any): any =>({...d,errorBar:i%4===0?{positive:5,negative:5,show:true,color:C.red,capSize:6}:undefined}));\n  const control: any=series('Control',C.muted,(t: any): any =>6+Math.sin(t*.4)*2);control.lineStyle='dashed';control.marker={show:false};\n  const opts: any=chartOptions('Cell density / synthetic experiment');opts.axes.x={...opts.axes.x,label:'Incubation time (h)',range:{min:0,max:24,step:4}};opts.axes.y={...opts.axes.y,label:'Relative density (%)',range:{min:0,max:110,step:20}};\n  return [await mountArt('10-line-chart.png',await p.createChart('line',[a,b,control],opts),{title:'Growth under uncertainty',subtitle:'Synthetic data · envelope ±5 units · error bars every four hours'})];\n}\n\nreturn {meta,run};\n})();"
