        "code": "// ===== EXAMPLE 14-scenes =====\nconst recipe14: Recipe = (() : any => {\n\nconst meta: any={id:'14',title:'The orbital observatory',category:'Scenes',description:'A layered observatory with nested clipped surfaces, transform-isolated instruments, a reusable scene builder and explicit preflight validation.'};\nasync function run(): Promise<any> {\n  const width: any=1440,height: any=1000,builder: any=p.createScene({width,height,background:{colorBg:C.night}});\n  builder.setBackground({gradientBg:linear(['#0e1725','#142f35'])});\n  const random: any=rng(19),starLayers: any=images(Array.from({length:190},(): any =>circle(40+random()*1360,205+random()*690,random()*1.4+.3,'#e3e9cf',{opacity:random()*.7+.1})));\n  builder.addLayer(starLayers).addLayers(heading('14 / SCENE SYSTEMS','The orbital observatory','Nested surfaces · deterministic draw order · isolated transforms',C.paper));\n  for(let k: any=0;k<6;k++)builder.addLayer({type:'path',path:[{type:'ellipse',x:725,y:610,radiusX:170+k*58,radiusY:85+k*27,rotation:-.45}],options:{stroke:{color:k===3?C.teal:'#547888',width:k===3?2:1},opacity:.55}});\n  builder.addLayer(images(circle(725,610,115,C.gold,{shape:{gradient:radial(['#fff4c6','#f7b465','#853951'])},shadow:{color:C.gold,blur:38,opacity:.3}})));\n  for(let k: any=0;k<5;k++){const [x,y]=polar(725,610,170+k*55,k*1.6-.5);builder.addLayer(images(circle(x,y,[12,21,16,28,9][k],[C.teal,C.blue,C.red,C.violet,C.paper][k])));}\n  const instrument: any={type:'surface',placement:{x:72,y:630,width:290,height:240,rotation:-6},background:{colorBg:C.panel,borderRadius:20,stroke:{color:'#2d5c68',width:1}},layers:[textLayer(txt('DEEP FIELD / 079',22,24,15,C.teal,{font:font(15,'mono')})),...Array.from({length:22},(_: any,i: any): any =>line([[20+i*11,178],[20+i*11,170-Math.sin(i*.65)*50-i*2]],C.teal,4)),textLayer(txt('SIGNAL LOCKED',24,201,13,C.paper,{font:font(13,'mono')}))]};\n  builder.addLayer(instrument);\n  const counter: any=textLayer(txt('6 ORBITS',1090,847,36,C.paper,{font:font(36,'bold')}));\n  builder.insertBefore(builder.layerCount-1,counter);\n  builder.insertAfter(builder.layerCount-1,textLayer(txt('APEX / TELEMETRY',64,942,16,C.teal,{font:font(16,'mono')})));\n  builder.insertLayer(1,line([[63,900],[1377,900]],'#42616d',1));\n  builder.insertLayers(2,[textLayer(txt('SIMULATED DATA',1130,46,14,C.teal,{font:font(14,'mono')}))]);\n  // A real edit cycle: replace the label, reorder the footer, remove a draft mark.\n  builder.replaceLayer(2,textLayer(txt('SIMULATED ORBITS',1098,46,14,C.teal,{font:font(14,'mono')})));\n  builder.addLayer(textLayer(txt('DRAFT',0,0))).removeLayer(builder.layerCount-1);\n  builder.moveLayer(1,builder.layerCount-1);\n  const input: any=builder.toRenderInput();p.validateSceneRenderInput(input);\n  const final: any=await builder.render();\n  const thumbnail: any=p.createScene(720,500);thumbnail.clearBackground().setBackground({colorBg:C.night}).addLayer({type:'imageBuffer',buffer:final,x:0,y:0,width:720,height:500});\n  const snapshot: any=thumbnail.toRenderInput().layers;thumbnail.clearLayers().replaceLayers(snapshot);\n  return [await save('14-scenes.png',final),await save('14-scene-thumbnail.png',await thumbnail.render()),await json('14-scene-structure.json',{rootLayers:builder.layerCount,nestedSurfaceCount:1,dimensions:{width,height}})];\n}\n\nreturn {meta,run};\n})();"
