        "code": "// ===== EXAMPLE 17-assets-and-plugins =====\nconst recipe17: Recipe = (() : any => {\n\nconst meta: any={id:'17',title:'An extensible engraving engine',category:'Assets & plugins',description:'A real engraving extension uses named palettes and values; registry replacement, resolution, installation and cleanup are exercised explicitly.'};\nasync function run(): Promise<any> {\n  const host: any=makePainter(),photo: any=await plate(200,200);\n  host.assets.loadPalette('brand',{paper:C.paper,ink:C.ink,accent:C.red});\n  host.assets.loadValue('edition',{number:79,density:90});\n  host.assets.loadImage('seal',photo).replaceImage('seal',photo);\n  host.assets.loadFont('heading',fontFile('bold')).replaceFont('heading',fontFile('bold'));\n  host.assets.replaceValue('edition',{number:79,density:100});\n  host.assets.replacePalette('brand',{paper:C.paper,ink:C.ink,accent:C.red});\n  await host.use({name:'engraving',async install(painter: any): Promise<any> {\n    painter.plugins.use('engraving',{toLayers({cx,cy,radius,phase=0}: any): any {\n      const accent: any=painter.assets.resolve('brand.accent');\n      return Array.from({length:80},(_: any,i: any): any =>line(Array.from({length:140},(_: any,j: any): any =>{\n        const u: any=j/139*2-1,x: any=u*radius;\n        return [cx+x,cy+(i-40)*5+Math.sin(u*4+phase+i*.035)*80*Math.sqrt(1-u*u)];\n      }),i%8===0?accent:'#68817b',i%8===0?2:.7,{opacity:.8}));\n    }});\n  }});\n  const api: any=host.plugins.get('engraving');\n  const layers: any=heading('17 / EXTENSION ARCHITECTURE','An extensible engraving engine','A trusted plugin builds normal scene layers and reads the caller’s named design tokens.');\n  layers.push(...api.toLayers({cx:710,cy:610,radius:580}),textLayer(txt('ENGRAVING / 079',64,926,18,C.ink,{font:font(18,'mono')})));\n  const prepared: any=host.prepareForRender({width:1440,height:1010,background:{colorBg:'$brand.paper'},layers});\n  const art: any=await host.renderScene(prepared);\n  const report: any={assets:host.assets.list(),hasBrand:host.assets.has('brand'),installed:host.plugins.listInstalled(),isInstalled:host.plugins.isInstalled('engraving'),apis:host.plugins.list(),hasApi:host.plugins.has('engraving')};\n  // Alternate installation entry for applications managing their own host object.\n  await host.plugins.install({name:'editionStamp',install(target: any): any {target.plugins.use('editionStamp',{number:79});}},host);\n  host.plugins.remove('editionStamp');host.plugins.remove('engraving');\n  host.assets.unregisterImage('seal').unregisterFont('heading').unregisterPalette('brand');host.assets.delete('edition');host.assets.clear();\n  return [await save('17-assets-and-plugins.png',art),await json('17-registry-report.json',report)];\n}\n\nreturn {meta,run};\n})();"
