        "language": "ts",
        "code": "// ===== EXAMPLE 20-runtime =====\nconst recipe20: Recipe = (() : any => {\n\n\nconst meta: any={id:'20',title:'The render flight recorder',category:'Runtime',description:'Policy resolution, configured limits, diagnostics, explicit preflight and structured failures are presented as a runtime instrument panel.'};\nasync function run(): Promise<any> {\n  const defaults: any=Apex.getDefaultApexifyRuntimeConfig(),resolved: any=Apex.resolveApexifyRuntimeConfig({limits:{maxBatchConcurrency:2}}),events: any=[],failures: any=[];\n  const record: any=async(label: any,fn: any): Promise<any> =>{try{await fn();throw new Error(`Expected failure: ${label}`);}catch(error: any){if(!(error instanceof Apex.ApexifyError))throw error;failures.push({label,class:error.constructor.name,code:error.code,message:error.message});}};\n  try{\n    Apex.configureApexifyRuntime({diagnostics:{handler:(event: any): any =>events.push({code:event.code,level:event.level})},cache:{maxEntries:32}});\n    await record('Invalid dimensions',(): any =>p.createCanvas({width:0,height:120}));\n    await record('Invalid configuration',(): any =>Apex.resolveApexifyRuntimeConfig({cache:{maxEntries:-1}}));\n    Apex.configureApexifyRuntime({limits:{maxTotalPixels:10000}});\n    await record('Pixel budget',(): any =>p.createCanvas({width:200,height:200}));\n    Apex.configureApexifyRuntime({limits:{maxTotalPixels:defaults.limits.maxTotalPixels}});\n    await record('Invalid image',(): any =>p.createImage({source:Buffer.from('not a PNG'),x:0,y:0},Buffer.from('not a PNG')));\n    await record('Missing asset',(): any =>p.assets.resolve('does_not_exist'));\n  }finally{Apex.resetApexifyRuntimeConfig();Apex.configureApexifyRuntime(defaults);}\n  const layers: any=heading('20 / RUNTIME CONTROL','The render flight recorder','Configuration is executable policy. These failures were produced and classified by the real API.');\n  failures.forEach((f: any,i: any): any =>{const y: any=260+i*124;layers.push(images(rect(64,y,1312,101,i%2?'#e6e4dc':'#ebe9e1',{borderRadius:12})),textLayer(txt(String(i+1).padStart(2,'0'),87,y+21,34,C.red,{font:font(34,'mono')}),txt(f.label,169,y+19,27,C.ink,{font:font(27,'bold')}),txt(f.code,169,y+59,15,C.muted,{font:font(15,'mono')}),txt(f.class,819,y+35,19,C.ink,{font:font(19,'mono')})));});\n  const errorTypes: any=['ApexifyError','ApexifyInputError','ApexifyConfigError','ApexifyResourceLimitError','ApexifyRemoteFetchError','ApexifyDecodeError','ApexifyProcessError','ApexifyExternalServiceError','ApexifyAssetError','ApexifyPluginError'];\n  return [await save('20-runtime.png',await scene(1440,980,layers)),await json('20-runtime-report.json',{failures,events,resolvedConcurrency:resolved.limits.maxBatchConcurrency,defaultPixelBudget:Apex.DEFAULT_APEXIFY_RUNTIME_CONFIG.limits.maxTotalPixels,errorTypes})];\n}\n\nreturn {meta,run};\n})();"
