        "language": "ts",
        "code": "// ===== EXAMPLE 21-audio =====\nconst recipe21: Recipe = (() : any => {\n\n\n\nconst meta: any={id:'21',title:'Signal archive',category:'Audio',description:'Stereo generative music, layered oscillators, ADSR, harmonics, noise, filters, panning, mixing, sequencing, composition and every sound preset.'};\nasync function run(): Promise<any> {\n  const synth: any=p.createAudio;\n  const pad: any=synth.synth({sampleRate:44100,channels:2,duration:8,seed:'peak-pad',masterGain:.5,layers:[\n    {waveform:'sine',frequency:110,duration:8,gain:.3,pan:-.5,partials:[[1,1],[2,.2],[3,.09]],adsr:{attack:1.2,decay:.4,sustain:.7,release:1.5},tremolo:{depth:.2,rate:.4}},\n    {waveform:'triangle',frequency:164.81,duration:8,gain:.16,pan:.6,detune:4,filter:{type:'lowpass',cutoff:1900},adsr:{attack:1.8,sustain:.65,release:1.5}},\n    {waveform:'pink',duration:8,gain:.025,filter:{type:'lowpass',cutoff:1200},adsr:{attack:2,sustain:.5,release:1.5}}\n  ]});\n  const noteOptions: any=(frequency: any): any =>({channels:2,sampleRate:44100,layers:[{waveform:'sine',frequency,duration:.8,gain:.32,partials:[[1,1],[2,.15],[4,.035]],vibrato:{depth:1.3,rate:5.5},adsr:{attack:.005,decay:.2,sustain:.15,release:.5}}]});\n  const notes: any=[220,329.63,440,493.88,659.25,493.88,440,329.63];\n  const sequence: any=synth.sequence({sampleRate:44100,channels:2,seed:79,tail:.2,events:Array.from({length:24},(_: any,i: any): any =>({at:i*.3,options:noteOptions(notes[i%8]),gain:.7}))});\n  const click: any=synth.custom({channels:2,sampleRate:44100,seed:'pulse',layers:[{waveform:'noise',duration:.07,gain:.08,filter:{type:'highpass',cutoff:4500},adsr:{attack:.001,decay:.02,sustain:0,release:.045}}]});\n  const accent: any=synth.preset('sparkle',{channels:2,sampleRate:44100,volume:.18,transpose:-5,seed:5});\n  const mix: any=synth.mix([{wav:pad,at:0,gain:.8},{wav:sequence,at:0,gain:.85}],{channels:2,sampleRate:44100,masterGain:.85,seed:'mix'});\n  const soundtrack: any=synth.compose({channels:2,sampleRate:44100,duration:8,seed:'final',masterGain:.9,clips:[{wav:mix,at:0,fadeIn:.12,fadeOut:1},{wav:accent,at:3.2,pan:.65,gain:.7},...Array.from({length:16},(_: any,i: any): any =>({wav:click,at:i*.45,pan:i%2?.7:-.7,fadeOut:.03}))]});\n  await synth.save(soundtrack,path.join(OUT,'21-signal-archive.wav'));\n  const layers: any=heading('21 / PROCEDURAL AUDIO','Signal archive','Eight seconds of original stereo synthesis, built from oscillators, envelopes and a deterministic score.',C.paper);\n  for(let ch: any=0;ch<2;ch++){\n    const path: any=waveform(soundtrack,960,ch).flatMap((bin: any,i: any): any =>[{type:'moveTo',x:90+i*1.28,y:410+ch*300-bin.max*135},{type:'lineTo',x:90+i*1.28,y:410+ch*300-bin.min*135}]);\n    layers.push({type:'path',path,options:{stroke:{color:ch?C.gold:C.teal,width:1}}});\n    layers.push(textLayer(txt(ch?'RIGHT CHANNEL':'LEFT CHANNEL',64,255+ch*300,16,C.paper,{font:font(16,'mono')})));\n  }\n  const files: any=['21-signal-archive.wav',await save('21-audio.png',await scene(1440,950,layers,{colorBg:C.night}))],presets: any=synth.listPresets(),presetLayers: any=heading('21 / PRESET COLLECTION','The complete sound palette',`${synth.presetNames.length} procedural sound identities. Every waveform below comes from an actual generated WAV.`);\n  for(let i: any=0;i<presets.length;i++){\n    const preset: any=presets[i],wav: any=synth.preset(preset.name,{seed:79,volume:.65});const x: any=64+i%3*450,y: any=252+Math.floor(i/3)*132;\n    presetLayers.push(textLayer(txt(preset.name,x,y,18,C.ink,{font:font(18,'mono')})));\n    waveform(wav,395).forEach((bin: any,j: any): any =>presetLayers.push(line([[x+j,y+66-bin.max*30],[x+j,y+66-bin.min*30]],i%2?C.red:'#137a69',1)));\n    files.push(await save(`21-preset-${preset.name}.wav`,wav));\n  }\n  // Preset waveforms are rendered in row strips to remain below scene-layer budgets.\n  // Collapse the dense line list to reusable paths before rendering.\n  const compact: any=[];let commands: any=[];\n  for(const layer of presetLayers){if(layer.type==='path'&&layer.path.length===2){commands.push(...layer.path);}else{if(commands.length){compact.push({type:'path',path:commands,options:{stroke:{color:'#137a69',width:1}}});commands=[];}compact.push(layer);}}\n  if(commands.length)compact.push({type:'path',path:commands,options:{stroke:{color:'#137a69',width:1}}});\n  files.push(await save('21-audio-presets.png',await scene(1440,270+Math.ceil(presets.length/3)*132,compact)));\n  const {data,...analysis}=parseWav(soundtrack);files.push(await json('21-audio-analysis.json',{...analysis,presets}));return files;\n}\n\nreturn {meta,run};\n})();"
