        "code": "// ===== EXAMPLE 23-animate =====\nconst recipe23: Recipe = (() : any => {\n\n\nconst meta: any={id:'23',title:'The kinetic loom',category:'Animation',description:'animate() drives a native drawing callback to weave a moving polar lattice. The callback is the API’s explicit custom-drawing extension.'};\nasync function run(): Promise<any> {\n  const width: any=640,height: any=480,count: any=40,callbacks: any=[];\n  const frames: any=Array.from({length:count},(_: any,frame: any): any =>({backgroundColor:C.night,duration:80,width,height,onDrawCustom(ctx: any): any {\n    const phase: any=frame/count*TAU;ctx.translate(width/2,height/2);\n    for(let i: any=0;i<90;i++){\n      const a: any=i/90*TAU,rad: any=155+Math.sin(a*6+phase)*22;\n      const b: any=a+1.8+.25*Math.sin(phase),end: any=170+Math.cos(b*4-phase)*20;\n      ctx.beginPath();ctx.moveTo(Math.cos(a)*rad,Math.sin(a)*rad);\n      ctx.bezierCurveTo(Math.cos(a+phase)*40,Math.sin(a+phase)*40,Math.cos(b-phase)*60,Math.sin(b-phase)*60,Math.cos(b)*end,Math.sin(b)*end);\n      ctx.strokeStyle=i%4?`rgba(54,217,180,0.3)`:'rgba(241,186,99,0.8)';ctx.lineWidth=i%4?1:1.7;ctx.stroke();\n    }\n    ctx.setTransform(1,0,0,1,0,0);ctx.fillStyle=C.paper;ctx.font='16px monospace';ctx.fillText('KINETIC LOOM / APEXIFY',24,33);\n  }}));\n  const paths: any=await p.animate(frames,80,width,height,{onStart:(): any =>callbacks.push('start'),onFrame:(i: any): any =>callbacks.push(i),onEnd:(): any =>callbacks.push('end')});\n  const result: any=await p.createGIF(paths.map((buffer: any): any =>({buffer,duration:80})),{outputFormat:'buffer',width,height,repeat:0,quality:5});\n  return [await save('23-animate.gif',result),await save('23-animate-poster.png',paths[8]),await json('23-animate-callbacks.json',callbacks)];\n}\n\nreturn {meta,run};\n})();"
