        "code": "// ===== EXAMPLE 26-capstone =====\nconst recipe26: Recipe = (() : any => {\n\n\nconst meta: any={id:'26',title:'Aster / a city made of signals',category:'Capstone',description:'A dense procedural isometric city combines painter-created polygon geometry, deterministic data, nested panels, charts, typography and component layers. This is 2.5D projection, not a 3D engine.'};\nasync function run(): Promise<any> {\n  const width: any=1800,height: any=1280,n: any=24,m: any=22,random: any=rng(1979),layers: any=[];\n  const project: any=(x: any,y: any,z: any=0): any =>({x:766+(x-y)*24,y:338+(x+y)*12-z});\n  const polygon: any=(points: any,color: any,stroke: any): any =>({type:'path',path:[{type:'polygon',points}],options:{fill:{color},...(stroke?{stroke:{color:stroke,width:.7}}:{})}});\n  layers.push(polygon([project(-1,-1),project(n+1,-1),project(n+1,m+1),project(-1,m+1)],'#cbded6'));\n  for(let x: any=0;x<=n;x++)layers.push(line([Object.values(project(x,0)),Object.values(project(x,m))],'#ebeee5',1));\n  for(let y: any=0;y<=m;y++)layers.push(line([Object.values(project(0,y)),Object.values(project(n,y))],'#ebeee5',1));\n  let buildings: any=0;\n  for(let diagonal: any=0;diagonal<n+m;diagonal++)for(let x: any=0;x<n;x++){\n    const y: any=diagonal-x;if(y<0||y>=m||x%7===0||y%6===0)continue;\n    const hill: any=Math.exp(-((x-13)**2+(y-10)**2)/95),z: any=18+hill*145+random()*47;\n    const a: any=project(x+.13,y+.13),b: any=project(x+.87,y+.13),c: any=project(x+.87,y+.87),d: any=project(x+.13,y+.87);\n    const at: any=project(x+.13,y+.13,z),bt: any=project(x+.87,y+.13,z),ct: any=project(x+.87,y+.87,z),dt: any=project(x+.13,y+.87,z);\n    const hero: any=hill>.72&&random()>.57;\n    layers.push(polygon([bt,b,c,ct],hero?'#a53d36':'#397f7a'),polygon([dt,ct,c,d],hero?'#d96d43':'#6eaaa0'),polygon([at,bt,ct,dt],hero?'#ffcb7e':'#c3ead4','#99beae'));\n    if(z>135&&buildings%4===0){const top: any=project(x+.5,y+.5,z);layers.push(line([[top.x,top.y],[top.x,top.y-18]],'#304e4d',1),images(circle(top.x,top.y-19,2,C.red)));}\n    buildings++;\n  }\n  const baseCity: any=await scene(width,height,layers,{colorBg:C.paper});\n  const curve: any=[series('Demand',C.red,(t: any): any =>42+Math.sin(t*.32)*24+t*.5,24),series('Renewables','#138878',(t: any): any =>54+Math.sin(t*.27-1)*21,24)];\n  const chart: any=await p.createChart('line',curve,{...chartOptions('24 HOUR ENERGY PROFILE',390,300),axes:{x:{color:C.muted,range:{min:0,max:24,step:6}},y:{color:C.muted,range:{min:0,max:100,step:25}}},legend:{show:false}});\n  const annotation: any=[...heading('26 / APEXIFY INTEGRATED SHOWCASE','Aster / a city made of signals','An original procedural city, generated entirely through the public Node APIs.',C.ink,width),\n    {type:'imageBuffer',buffer:chart,x:1340,y:620,width:395,height:300},\n    textLayer(txt('SYNTHETIC\\nURBAN SYSTEM',1349,290,25,C.ink,{font:font(25,'bold'),layout:{lineHeight:1.2}}),txt(String(buildings),1343,378,104,C.red,{font:font(104,'bold')}),txt('PROCEDURAL BUILDINGS',1350,495,15,C.muted,{font:font(15,'mono')}),txt('A 24 × 22 spatial field, projected\\ninto two dimensions. Every roof,\\nwall, street and signal is code.',1350,540,17,C.ink,{layout:{lineHeight:1.6}}),txt('FORM FOLLOWS DATA.',64,1138,46,C.ink,{font:font(46,'serif')}),txt('APEXIFY / PEAK LAB / 026',64,1220,16,C.muted,{font:font(16,'mono')})),\n    ...p.components.progressBar.toLayers({x:1350,y:966,width:365,height:16,value:78,max:100,fill:'#168c78',background:'#d7ddd4',radius:6}),textLayer(txt('SIMULATED RENEWABLE SHARE',1350,930,13,C.muted,{font:font(13,'mono')}),txt('78%',1350,1009,61,'#168c78',{font:font(61,'bold')}))\n  ];\n  const final: any=await scene(width,height,[{type:'imageBuffer',buffer:baseCity,x:0,y:0},...annotation]);\n  return [await save('26-capstone.png',final),await json('26-city-metadata.json',{buildings,grid:{x:n,y:m},projection:'2.5D isometric, generated application geometry',data:'synthetic',apis:['renderScene','createChart','components.progressBar.toLayers']})];\n}\n\nreturn {meta,run};\n})();"
